-- Test scripts generated by the Test Script Agent while a Request is executing (docs/integrate/TDD-REQ-TESTSCRIPT-001). One row per
-- attempt; is_current = 1 marks the one the screen shows. Neither the code lane nor the test-spec lane reads it.
CREATE TABLE request.request_test_script_runs (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL,
    request_id UUID NOT NULL REFERENCES request.requests(id),
    attempt INT NOT NULL DEFAULT 1,
    status TEXT NOT NULL CHECK (status IN ('pending','running','completed','needs_review','blocked','failed','skipped','cancelled')),
    reason_code TEXT NOT NULL DEFAULT '',
    reason_message TEXT NOT NULL DEFAULT '',
    -- The test-spec attempt whose TCIR was read; no foreign key so the two lanes stay independent.
    test_spec_run_id TEXT NOT NULL DEFAULT '',
    feature TEXT NOT NULL DEFAULT '',
    spec_version INT NOT NULL DEFAULT 0,
    tsa_job_id TEXT NOT NULL DEFAULT '',
    branch TEXT NOT NULL DEFAULT '',
    base_ref TEXT NOT NULL DEFAULT '',
    worktree_path TEXT NOT NULL DEFAULT '',
    commit_sha TEXT NOT NULL DEFAULT '',
    summary JSONB NOT NULL DEFAULT '{}'::jsonb,
    started_by UUID NULL,
    started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at TIMESTAMPTZ NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    is_current SMALLINT NULL CHECK (is_current = 1),
    superseded_at TIMESTAMPTZ NULL,
    lease_owner TEXT NOT NULL DEFAULT '',
    lease_until TIMESTAMPTZ NOT NULL DEFAULT '2000-01-01'
);

CREATE UNIQUE INDEX request_test_script_runs_one_current ON request.request_test_script_runs (tenant_id, request_id, is_current);
CREATE INDEX request_test_script_runs_history ON request.request_test_script_runs (tenant_id, request_id, attempt DESC);
CREATE INDEX request_test_script_runs_active ON request.request_test_script_runs (status, updated_at) WHERE is_current = 1 AND status IN ('pending','running');

ALTER TABLE request.request_test_script_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE request.request_test_script_runs FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON request.request_test_script_runs
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

-- The reconcile pass picks candidates across tenants (relay access, read only); the per-row lease keeps replicas apart.
CREATE POLICY relay_scan ON request.request_test_script_runs
    AS PERMISSIVE FOR SELECT
    USING (current_setting('app.relay', true) = 'on');
